applicationScript.applicationJavaScript:
/**
 * @id ExampleScript
 * @description ${DESCRIPTION}
 * @interval 0
 * @observe app.example.enabled
 * @ui
 * {
 *   "slot": "applicationScript",
 *   "id": "example-settings",
 *   "title": "示例设置",
 *   "scope": "persistent",
 *   "components": [
 *     {
 *       "id": "enabled",
 *       "type": "toggle",
 *       "label": "启用",
 *       "description": "控制示例功能",
 *       "bindings": {
 *         "value": {
 *           "path": "app.example.enabled",
 *           "type": "boolean",
 *           "default": true
 *         }
 *       }
 *     },
 *     {
 *       "id": "tags",
 *       "type": "choice",
 *       "label": "标签",
 *       "description": "UI 专用多选字段由宿主管理",
 *       "selectionMin": 0,
 *       "selectionMax": 2,
 *       "options": [
 *         { "label": "原生", "value": "native" },
 *         { "label": "动态", "value": "dynamic" }
 *       ],
 *       "bindings": {
 *         "value": {
 *           "path": "app.example.tags",
 *           "type": "list",
 *           "default": ["native"]
 *         }
 *       }
 *     },
 *     {
 *       "id": "status",
 *       "type": "text",
 *       "label": "状态",
 *       "copyable": true,
 *       "bindings": {
 *         "text": {
 *           "path": "app.example.status",
 *           "fallback": "已启用"
 *         }
 *       }
 *     }
 *   ]
 * }
 */
let enabled = null;
let status = null;

function updateStatus(value) {
  if (status) status.value = value ? '已启用' : '已停用';
}

defineQuScript({
  onStart(qu) {
    enabled = qu.viewModel.define(
      'app.example.enabled', 'boolean', true,
      { label: '启用', persistent: true }
    );
    status = qu.viewModel.define(
      'app.example.status', 'string', '已启用',
      { label: '状态' }
    );
    updateStatus(enabled.value);
  },
  onInterval() {
  },
  onValue(path, value) {
    if (path === 'app.example.enabled') updateStatus(value);
  },
  onUiAction() {
  },
  onStop() {
    enabled = null;
    status = null;
  }
});

resourcePackage.mainJavaScript:
let stops = [];
defineResourcePackage({
  activate(qu) {
    stops = [];
  },
  deactivate() {
    stops.forEach(stop => stop());
    stops = [];
  }
});
